import { CallHandler, ExecutionContext, Injectable, NestInterceptor } from "@nestjs/common"
import { Observable } from "rxjs"

@Injectable()
export class MyInterceptor implements NestInterceptor {
    intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
        console.log("handler'dan OLDIN")        // 1) so'rov keldi

        const http = context.switchToHttp()
        const req = http.getRequest()           // req.method, req.url, req.headers, req.body
        const res = http.getResponse()          // status va sarlavhalar
        context.getClass().name                 // "CatsController"
        context.getHandler().name               // "findAll"
        context.getType()                       // "http" | "rpc" | "ws"

        return next.handle()                    // 2) handler'ni ishga tushiradi; natija — Observable
    }
}

@Controller("cats")
@UseInterceptors(LoggingInterceptor)          // controller'dagi barcha endpoint'lar
export class CatsController {
    @Get()
    @UseInterceptors(TimeoutInterceptor)      // faqat shu metod
    findAll() { /* ... */ }
}

// Global — 1) main.ts: modul tashqarisida, DI ishlamaydi
app.useGlobalInterceptors(new LoggingInterceptor())

// Global — 2) modul ichida: DI ishlaydi (tavsiya etiladi)
@Module({ providers: [{ provide: APP_INTERCEPTOR, useClass: LoggingInterceptor }] })
export class AppModule {}

@Injectable()
export class FlagInterceptor implements NestInterceptor {
    constructor(private readonly flags: FlagsService) {}       // DI

    // intercept() async bo'lishi mumkin: Promise<Observable> qaytaradi
    async intercept(context: ExecutionContext, next: CallHandler) {
        if (context.getType() === "http") {                    // faqat HTTP uchun
            if (!(await this.flags.isEnabled("beta"))) throw new NotFoundException()
        }
        return next.handle()
    }
}

