import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, UseInterceptors } from "@nestjs/common"
import { of, tap } from "rxjs"

@Injectable()
class SimpleCacheInterceptor implements NestInterceptor {
    private cache = new Map<string, unknown>()
    intercept(ctx: ExecutionContext, next: CallHandler) {
        const key = ctx.switchToHttp().getRequest().url
        if (this.cache.has(key)) return of(this.cache.get(key))            // handler chaqirilmaydi
        return next.handle().pipe(tap(data => this.cache.set(key, data)))
    }
}

let computed = 0
@Controller("rates") @UseInterceptors(SimpleCacheInterceptor)
class RatesController { @Get() get() { computed++; return { USD: 12650, computed } } }
@Module({ controllers: [RatesController] }) class AppModule {}

