import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, SetMetadata } from "@nestjs/common"
import { APP_INTERCEPTOR, Reflector } from "@nestjs/core"
import { map } from "rxjs"

const SkipWrap = () => SetMetadata("skipWrap", true)

@Injectable()
class WrapInterceptor implements NestInterceptor {
    constructor(private readonly reflector: Reflector) {}
    intercept(ctx: ExecutionContext, next: CallHandler) {
        if (this.reflector.get<boolean>("skipWrap", ctx.getHandler())) return next.handle()
        return next.handle().pipe(map(data => ({ data })))
    }
}

