import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, NotFoundException, UseInterceptors } from "@nestjs/common"

const loadFlag = async (name: string, beta: boolean) => {
    await new Promise(r => setTimeout(r, 5))          // masalan, bazadan o'qish
    return name === "new-checkout" ? beta : true
}

@Injectable()
class FeatureFlagInterceptor implements NestInterceptor {
    async intercept(ctx: ExecutionContext, next: CallHandler) {
        const beta = ctx.switchToHttp().getRequest().headers["x-beta"] === "1"
        if (!(await loadFlag("new-checkout", beta))) throw new NotFoundException("Bu funksiya hali yoqilmagan")
        return next.handle()
    }
}

