import { CallHandler, ExecutionContext, Injectable, NestInterceptor } from "@nestjs/common"
import { firstValueFrom, of } from "rxjs"

@Injectable()
class ContextAwareInterceptor implements NestInterceptor {
    intercept(ctx: ExecutionContext, next: CallHandler) {
        const type = ctx.getType()                   // "http" | "rpc" | "ws"
        if (type === "http") console.log(`[http] ${ctx.switchToHttp().getRequest().url}`)
        else if (type === "rpc") console.log(`[rpc] ${JSON.stringify(ctx.switchToRpc().getData())}`)
        else console.log(`[${type}] qo'llab-quvvatlanmaydi`)
        return next.handle()
    }
}

// Haqiqiy ilova o'rniga sodda "soxta" kontekstlar
const httpCtx = { getType: () => "http", switchToHttp: () => ({ getRequest: () => ({ url: "/users" }) }) }
const rpcCtx = { getType: () => "rpc", switchToRpc: () => ({ getData: () => ({ userId: 7 }) }) }
const handler: CallHandler = { handle: () => of("ok") }

async function main() {
    const interceptor = new ContextAwareInterceptor()
    for (const ctx of [httpCtx, rpcCtx]) {
        await firstValueFrom(interceptor.intercept(ctx as unknown as ExecutionContext, handler))
    }
}
