import { CallHandler, ExecutionContext, Injectable, NestInterceptor, RequestTimeoutException } from "@nestjs/common"
import { catchError, firstValueFrom, NEVER, throwError, timeout, TimeoutError } from "rxjs"
import assert from "node:assert/strict"

@Injectable()
class TimeoutInterceptor implements NestInterceptor {
    constructor(private readonly ms: number) {}
    intercept(_ctx: ExecutionContext, next: CallHandler) {
        return next.handle().pipe(
            timeout(this.ms),
            catchError(err => throwError(() => err instanceof TimeoutError ? new RequestTimeoutException() : err)),
        )
    }
}

async function main() {
    const neverReplies: CallHandler = { handle: () => NEVER }       // handler hech qachon javob bermaydi
    const result = firstValueFrom(new TimeoutInterceptor(20).intercept({} as ExecutionContext, neverReplies))
    await assert.rejects(result, (err: unknown) => err instanceof RequestTimeoutException && err.getStatus() === 408)
    console.log("✔ 20ms ichida javob kelmadi → RequestTimeoutException (408)")
}
main()

import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor } from "@nestjs/common"
