import { BadRequestException, CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, ServiceUnavailableException, UseInterceptors } from "@nestjs/common"
import { retry, throwError, timer } from "rxjs"

@Injectable()
class SmartRetryInterceptor implements NestInterceptor {
    intercept(_ctx: ExecutionContext, next: CallHandler) {
        // next.handle() har obunada handler'ni qaytadan ishga tushiradi, shuning uchun retry ishlaydi
        return next.handle().pipe(retry({
            count: 2,
            delay: err => err instanceof ServiceUnavailableException ? timer(10) : throwError(() => err),
        }))
    }
}

const calls = { flaky: 0, invalid: 0 }

@Controller()
@UseInterceptors(SmartRetryInterceptor)
class AppController {
    @Get("flaky") flaky() {
        if (++calls.flaky < 3) throw new ServiceUnavailableException("band")
        return { calls: calls.flaky }
    }
    @Get("invalid") invalid() {
        calls.invalid++
        throw new BadRequestException("noto'g'ri so'rov")
    }
}

@Module({ controllers: [AppController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/flaky")
    await http.get("/invalid")
    console.log("invalid chaqirilgan:", calls.invalid, "marta")
    await http.close()
}
