import { ArgumentsHost, BadRequestException, CallHandler, CanActivate, Catch, Controller, ExceptionFilter, ExecutionContext, Get, HttpException, Injectable, MiddlewareConsumer, Module, NestInterceptor, NestModule, Param, PipeTransform, UseFilters, UseGuards, UseInterceptors } from "@nestjs/common"
import type { NextFunction, Request, Response } from "express"
import { tap } from "rxjs"

const log = (s: string) => console.log("  " + s)

function tracer(_req: Request, _res: Response, next: NextFunction) { log("1. middleware"); next() }

@Injectable()
class TraceGuard implements CanActivate {
    canActivate() { log("2. guard"); return true }
}

@Injectable()
class TraceInterceptor implements NestInterceptor {
    intercept(_ctx: ExecutionContext, next: CallHandler) {
        log("3. interceptor (oldin)")
        return next.handle().pipe(tap({
            next: () => log("6. interceptor (keyin)"),
            error: () => log("6. interceptor (xato)"),
        }))
    }
}

@Injectable()
class TracePipe implements PipeTransform {
    transform(value: string) { log("4. pipe"); return value }
}

@Catch(HttpException)
class TraceFilter implements ExceptionFilter {
    catch(e: HttpException, host: ArgumentsHost) {
        log("7. exception filter")
        host.switchToHttp().getResponse<Response>().status(e.getStatus()).json({ error: e.message })
    }
}

@Controller("flow")
@UseGuards(TraceGuard)
@UseInterceptors(TraceInterceptor)
@UseFilters(TraceFilter)
class FlowController {
    @Get(":id")
    get(@Param("id", TracePipe) id: string) {
        log("5. handler")
        if (id === "0") throw new BadRequestException("nol mumkin emas")
        return id
    }
}

@Module({ controllers: [FlowController] })
class AppModule implements NestModule {
    configure(consumer: MiddlewareConsumer) { consumer.apply(tracer).forRoutes(FlowController) }
}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/flow/7")
    await http.get("/flow/0")
    await http.close()
}
