import { tap } from "rxjs"

const buckets: Record<string, number> = { "<10ms": 0, "10-50ms": 0, ">50ms": 0 }
@Injectable() class Histo implements NestInterceptor {
    // Haqiqiy loyihada: d = Date.now() - boshlanish. Bu yerda natija barqaror bo'lishi uchun handler davomiylikni o'zi qaytaradi.
    intercept(_c: ExecutionContext, n: CallHandler) { return n.handle().pipe(tap(({ tookMs: d }: { tookMs: number }) => { buckets[d < 10 ? "<10ms" : d <= 50 ? "10-50ms" : ">50ms"]++ })) }
}
@Controller("h") @UseInterceptors(Histo) class H { @Get(":ms") h(@Param("ms") ms: string) { return { tookMs: Number(ms) } } }
@Module({ controllers: [H] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const url = await http.app.getUrl()
    for (const ms of [3, 7, 25, 80]) await fetch(url + "/h/" + ms)
    console.log(buckets)
    await http.close()
}
main()

