import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, UseInterceptors } from "@nestjs/common"
import { createHash } from "node:crypto"
import { map } from "rxjs"

@Injectable()
class HashHeaderInterceptor implements NestInterceptor {
    intercept(ctx: ExecutionContext, next: CallHandler) {
        const res = ctx.switchToHttp().getResponse()
        return next.handle().pipe(map(data => {
            res.setHeader("X-Content-Hash", createHash("sha1").update(JSON.stringify(data)).digest("hex").slice(0, 10))
            return data
        }))
    }
}

let price = 25000
@Controller("price") @UseInterceptors(HashHeaderInterceptor)
class PriceController { @Get() get() { return { choy: price } } }
@Module({ controllers: [PriceController] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const h1 = (await http.get("/price")).headers.get("x-content-hash")
    const h2 = (await http.get("/price")).headers.get("x-content-hash")
    price = 27000
    const h3 = (await http.get("/price")).headers.get("x-content-hash")
    console.log("bir xil mazmun — bir xil xesh:", h1 === h2, "| narx o'zgargach boshqa:", h1 !== h3)
    await http.close()
}
main()

