    intercept(c: ExecutionContext, n: CallHandler) {
        const admin = c.switchToHttp().getRequest().headers["x-role"] === "admin"
        return n.handle().pipe(map((u: Record<string, unknown>) => (admin ? u : { id: u.id, name: u.name })))
    }
}
@Controller("user") @UseInterceptors(RoleView) class U { @Get() u() { return { id: 1, name: "Ali", email: "ali@mail.uz", salary: 9000 } } }
@Module({ controllers: [U] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/user")
    await http.get("/user", { "X-Role": "admin" })
    await http.close()
}
main()

import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, UseInterceptors } from "@nestjs/common"
