@Injectable() class SortKeys implements NestInterceptor { intercept(_c: ExecutionContext, n: CallHandler) { return n.handle().pipe(map((o: Record<string, unknown>) => Object.fromEntries(Object.keys(o).sort().map(k => [k, o[k]])))) } }
@Controller("cfg") @UseInterceptors(SortKeys) class C { @Get() c() { return { zeta: 1, alpha: 2, mid: 3 } } }
@Module({ controllers: [C] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/cfg")
    await http.close()
}
main()

import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, UseInterceptors } from "@nestjs/common"
import { map } from "rxjs"

const trimAll = (v: unknown): unknown => typeof v === "string" ? v.trim() : Array.isArray(v) ? v.map(trimAll) : v && typeof v === "object" ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, trimAll(x)])) : v
@Injectable() class Trim implements NestInterceptor { intercept(_c: ExecutionContext, n: CallHandler) { return n.handle().pipe(map(trimAll)) } }
@Controller("t") @UseInterceptors(Trim) class T { @Get() t() { return { name: "  Ali  ", tags: [" ts ", "nest  "] } } }
@Module({ controllers: [T] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/t")
    await http.close()
}
main()

import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, SetMetadata } from "@nestjs/common"
import { APP_INTERCEPTOR, Reflector } from "@nestjs/core"
import { map } from "rxjs"

const Envelope = (key: string) => SetMetadata("envelope", key)
@Injectable() class Env implements NestInterceptor {
    constructor(private r: Reflector) {}
    intercept(c: ExecutionContext, n: CallHandler) { const key = this.r.get<string>("envelope", c.getHandler()) ?? "data"; return n.handle().pipe(map(d => ({ [key]: d }))) }
}
@Controller() class C { @Get("users") @Envelope("users") u() { return ["ali"] } @Get("misc") m() { return 1 } }
@Module({ controllers: [C], providers: [{ provide: APP_INTERCEPTOR, useClass: Env }] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/users"); await http.get("/misc")
    await http.close()
}
main()

import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, UseInterceptors } from "@nestjs/common"
import type { Response } from "express"
import { map } from "rxjs"

@Injectable() class Csv implements NestInterceptor {
    intercept(c: ExecutionContext, n: CallHandler) {
        const wantsCsv = String(c.switchToHttp().getRequest().headers.accept).includes("text/csv")
        return n.handle().pipe(map((rows: Record<string, unknown>[]) => {
            if (!wantsCsv) return rows
            c.switchToHttp().getResponse<Response>().type("text/csv")
            return [Object.keys(rows[0]).join(","), ...rows.map(r => Object.values(r).join(","))].join("\n")
        }))
    }
}
@Controller("export") @UseInterceptors(Csv) class E { @Get() e() { return [{ id: 1, name: "Ali" }, { id: 2, name: "Vali" }] } }
@Module({ controllers: [E] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/export")
    await http.get("/export", { Accept: "text/csv" })
    await http.close()
}
main()

import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, Post, UseInterceptors } from "@nestjs/common"
import type { Response } from "express"

@Injectable() class CacheHeaders implements NestInterceptor {
    intercept(c: ExecutionContext, n: CallHandler) { const req = c.switchToHttp().getRequest(); c.switchToHttp().getResponse<Response>().setHeader("Cache-Control", req.method === "GET" ? "public, max-age=300" : "no-store"); return n.handle() }
}
@Controller("c") @UseInterceptors(CacheHeaders) class C { @Get() g() { return "" } @Post() p() { return "" } }
@Module({ controllers: [C] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const url = await http.app.getUrl()
    console.log("GET:", (await fetch(url + "/c")).headers.get("cache-control"))
    console.log("POST:", (await fetch(url + "/c", { method: "POST" })).headers.get("cache-control"))
    await http.close()
}
main()

import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor } from "@nestjs/common"
import { APP_INTERCEPTOR } from "@nestjs/core"
import { map } from "rxjs"

@Injectable()
class EnvelopeInterceptor implements NestInterceptor {
    intercept(_ctx: ExecutionContext, next: CallHandler) {
        return next.handle().pipe(map(data => ({ success: true, data })))
    }
}

@Controller()
class AppController {
    @Get("hello") hello() { return "salom" }
}

@Module({
    controllers: [AppController],
    providers: [{ provide: APP_INTERCEPTOR, useClass: EnvelopeInterceptor }],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/hello")
    await http.get("/nope")
    await http.close()
}
main()

import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, UseInterceptors } from "@nestjs/common"
import { map } from "rxjs"

type User = { id: number; name: string; password?: string }

@Injectable()
class UsersService {
    private users: User[] = [{ id: 1, name: "Ali", password: "hash-1" }]
    all() { return this.users }                                  // ichki ro'yxatning o'zi, nusxa emas
    passwordOf(id: number) { return this.users.find(u => u.id === id)?.password }
}

@Injectable()
class MutatingInterceptor implements NestInterceptor {
    intercept(_ctx: ExecutionContext, next: CallHandler) {
        return next.handle().pipe(map((users: User[]) => {
            users.forEach(u => delete u.password)                // XATO: asl obyekt o'zgaradi
            return users
        }))
    }
}

@Injectable()
class CopyingInterceptor implements NestInterceptor {
    intercept(_ctx: ExecutionContext, next: CallHandler) {
        return next.handle().pipe(map((users: User[]) =>
            users.map(({ password, ...rest }) => rest)))         // TO'G'RI: yangi obyektlar
    }
}

@Controller("users")
class UsersController {
    constructor(private readonly users: UsersService) {}
    @Get("safe") @UseInterceptors(CopyingInterceptor) safe() { return this.users.all() }
    @Get("bad") @UseInterceptors(MutatingInterceptor) bad() { return this.users.all() }
}

@Module({ controllers: [UsersController], providers: [UsersService] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const service = http.app.get(UsersService)
    await http.get("/users/safe")
    console.log("safe'dan keyin parol:", service.passwordOf(1))
    await http.get("/users/bad")
    console.log("bad'dan keyin parol:", service.passwordOf(1))
    await http.close()
}
main()

import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, RequestTimeoutException, UseInterceptors } from "@nestjs/common"
import { throwError, timeout } from "rxjs"

const sleep = (ms: number) => new Promise(r => setTimeout(r, ms))

@Injectable()
class TimeoutInterceptor implements NestInterceptor {
    intercept(_ctx: ExecutionContext, next: CallHandler) {
        return next.handle().pipe(
            timeout({ each: 20, with: () => throwError(() => new RequestTimeoutException("Kutish vaqti tugadi")) }),
        )
    }
}

@Controller("payments")
@UseInterceptors(TimeoutInterceptor)
class PaymentsController {
    @Get() async pay() {
        await sleep(80)
        console.log("  [handler] to'lov amalga oshdi")          // 408 dan KEYIN ham bajariladi
        return { paid: true }
    }
}

@Module({ controllers: [PaymentsController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/payments")
    await sleep(120)                                            // handler tugashini kutamiz
    await http.close()
}
main()
